function _setReserveFactorFresh(uint newReserveFactorMantissa) internal returns (uint) {
    // Check caller is admin
    if (msg.sender != admin) {
        return fail(Error.UNAUTHORIZED, FailureInfo.SET_RESERVE_FACTOR_ADMIN_CHECK);
    }

    // Verify market's block number equals current block number
    if (accrualBlockNumber != getBlockNumber()) {
        return fail(Error.MARKET_NOT_FRESH, FailureInfo.SET_RESERVE_FACTOR_FRESH_CHECK);
    }

    // Check newReserveFactor ≤ maxReserveFactor
    if (newReserveFactorMantissa > reserveFactorMaxMantissa) {
        return fail(Error.BAD_INPUT, FailureInfo.SET_RESERVE_FACTOR_BOUNDS_CHECK);
    }

    uint oldReserveFactorMantissa = reserveFactorMantissa;
    reserveFactorMantissa = newReserveFactorMantissa;

    emit NewReserveFactor(oldReserveFactorMantissa, newReserveFactorMantissa);

    return uint(Error.NO_ERROR);
}

function _setCloseFactor(uint newCloseFactorMantissa) external returns (uint) {
    // Check caller is admin
    if (msg.sender != admin) {
        return fail(Error.UNAUTHORIZED, FailureInfo.SET_CLOSE_FACTOR_OWNER_CHECK);
    }

    uint oldCloseFactorMantissa = closeFactorMantissa;
    closeFactorMantissa = newCloseFactorMantissa;
    emit NewCloseFactor(oldCloseFactorMantissa, newCloseFactorMantissa);

    return uint(Error.NO_ERROR);
}

function setText(
    bytes32 node,
    string calldata key,
    string calldata value
) external virtual authorised(node) {
    versionable_texts[recordVersions[node]][node][key] = value;
    emit TextChanged(node, key, key, value);
}

function setDefaultFeeByFeeTier(uint24 feeTier, uint8 defaultFeeValue) external onlyFeeSetter {
  require(_feeTierExists(feeTier), InvalidFeeTier());
  defaultFees[feeTier] = defaultFeeValue;
}

function setParameter(Parameter param, uint256 value) external onlyOwner whenNotPaused {
    parameters[param] = value;
    emit ParameterUpdated(param, value);
}

function setTaxPercentage(uint256 _taxPercentage) external {
    require(_taxPercentage >= 100, "Tax percentage too small");
    require(_taxPercentage <= 10000, "Tax percentage cannot exceed 100%");
    require(msg.sender == owner, "Only the owner can set the tax percentage");
    taxPercentage = _taxPercentage;
    emit TaxChanged(_taxPercentage);
}

function updateInvoicePaymentReceiver(address _newInvoicePaymentReceiver) external onlyRole(DEFAULT_ADMIN_ROLE) {
  if (_newInvoicePaymentReceiver == address(0)) {
    revert ZeroAddressNotAllowed();
  }
  emit InvoicePaymentReceiverUpdated(invoicePaymentReceiver, _newInvoicePaymentReceiver);
  invoicePaymentReceiver = _newInvoicePaymentReceiver;
}

function registerAllocator(address allocatorId, bytes calldata metadata) external returns (bool) {
    require(allocatorId != address(0), "Invalid allocator ID");
    allocatorMetadata[allocatorId] = metadata;
    emit AllocatorRegistered(allocatorId, metadata);
    return true;
}

function mint(address _to, uint256 _amount) external onlyRole(MINTER_ROLE) {
    require(_to != address(0), "Cannot mint to zero address");
    require(totalMinted + _amount <= MINT_CAP, "Exceeds mint cap");
    totalMinted += _amount;
    token.mint(_to, _amount);
    emit Minted(_to, _amount);
}
